const icons={discover:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',saved:'<path d="M6 3h12v18l-6-4-6 4z"/>',intro:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',plan:'<path d="m12 3 3 6 6 3-6 3-3 6-6-3 6-3z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',roles:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 4V2m8 2V2M8 10h8m-8 4h8"/>',pipeline:'<circle cx="4" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="20" cy="12" r="2"/><path d="M6 12h4m4 0h4"/>',company:'<path d="M3 21V7l9-4 9 4v14zM9 21v-6h6v6M7 10h2m6 0h2"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2a7 7 0 0 1 14 0v2m1-14a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 12h4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.discover}</svg>`;
const talents=[
{id:1,name:'Sarah Lim',role:'Marketing Executive',category:'Marketing',years:4,initials:'SL',color:'#e6ecfa',ink:'#586daf',skills:['Campaign strategy','CRM','Content marketing'],note:'Connects campaign planning with hands-on execution. Experienced with growing consumer brands.',achievement:'Coordinated a product launch across email, social and retail teams, delivering 1,200 event registrations.',salary:'S$4,000–5,000',availability:'Within 1 month'},
{id:2,name:'Marcus Tan',role:'Business Development Manager',category:'Business development',years:6,initials:'MT',color:'#e5ede5',ink:'#5e7861',skills:['Partnerships','B2B growth','Negotiation'],note:'Builds lasting SME partnerships. Looking to help a growing business open new markets.',achievement:'Built a partner channel from the ground up and onboarded 12 active business partners.',salary:'S$5,500–7,000',availability:'Within 1 month'},
{id:3,name:'Priya Kumar',role:'HR Executive',category:'HR',years:3,initials:'PK',color:'#f5e9de',ink:'#9b7959',skills:['Onboarding','HR operations','Employee experience'],note:'Brings structure to people operations. Comfortable supporting small, fast-growing teams.',achievement:'Created an onboarding checklist and coordinated the first month for 30 new colleagues.',salary:'S$3,500–4,500',availability:'Immediately'},
{id:4,name:'Daniel Wong',role:'Account Executive',category:'Sales',years:5,initials:'DW',color:'#e1edf2',ink:'#527a8d',skills:['Consultative sales','Account management','SaaS'],note:'Combines new-business sales with account care. Interested in consultative B2B roles.',achievement:'Achieved 120% of quarterly sales target while managing a portfolio of 35 SME customers.',salary:'S$4,500–6,000',availability:'Within 1 month'},
{id:5,name:'Aisha Rahman',role:'Office Administrator',category:'Administration',years:4,initials:'AR',color:'#efe6f1',ink:'#946e9c',skills:['Office operations','Vendor coordination','Scheduling'],note:'Keeps busy offices running smoothly. Experienced in vendor and calendar coordination.',achievement:'Coordinated an office move for 45 employees and maintained day-to-day operations throughout.',salary:'S$3,000–4,000',availability:'Immediately'},
{id:6,name:'Ethan Lee',role:'Operations & Admin Executive',category:'Administration',years:2,initials:'EL',color:'#f1ecd9',ink:'#988451',skills:['Process improvement','Excel','Event coordination'],note:'Detail-oriented support for growing teams, with practical spreadsheet and process skills.',achievement:'Reorganised purchasing records into a shared tracker used by three departments.',salary:'S$2,800–3,500',availability:'Within 1 month'}];
let state={view:'overview',mode:'employer',search:'',category:'All functions',available:'Any availability',saved:new Set(),requests:[],plan:'Free',profile:{name:'Sarah Lim',role:'Marketing Executive',salary:'S$4,000–5,000',availability:'Within 1 month',interest:'Campaign marketing roles in growing consumer businesses',visibility:'Discoverable'}};
// Employer data is illustrative and exists only for this page session.
const employerDemo={newMatches:24,interviewsThisWeek:3,roles:[
  {id:1,title:'Business Development Executive',location:'Singapore',salary:'SGD 3.5K – 5K',matches:18,shortlisted:6,interviewing:3,category:'Business development',talentIds:[2,4],status:'Active'},
  {id:2,title:'Marketing Executive',location:'Singapore',salary:'SGD 3K – 4.5K',matches:12,shortlisted:4,interviewing:2,category:'Marketing',talentIds:[1],status:'Active'},
  {id:3,title:'Account Manager',location:'Singapore',salary:'SGD 4K – 6K',matches:9,shortlisted:3,interviewing:1,category:'Sales',talentIds:[4,2],status:'Active'}
],attention:[
  {id:1,name:'Marcus Tan',role:'Business Development Executive',detail:'Interview completed 4 days ago',status:'Awaiting outcome',stage:'Interview',tone:'attention',talentId:2,roleId:1,kind:'candidate'},
  {id:2,name:'Sarah Lim',role:'Marketing Executive',detail:'Introduction accepted 6 days ago',status:'Follow up',stage:'Talent Interested',tone:'attention',talentId:1,roleId:2,kind:'candidate'},
  {id:3,name:'BD Executive',role:'Business Development Executive',detail:'No activity for 17 days',status:'Stale',stage:'Active',tone:'stale',roleId:1,kind:'role'},
  {id:4,name:'Daniel Wong',role:'Account Manager',detail:'Interview completed 2 days ago',status:'Awaiting outcome',stage:'Interview',tone:'attention',talentId:4,roleId:3,kind:'candidate'}
],topMatches:[
  {talentId:4,roleId:1,score:91,reasons:['Relevant B2B experience','Client management skills','Salary aligned'],gap:'Business development title differs from current role'},
  {talentId:1,roleId:2,score:87,reasons:['Campaign strategy experience','CRM and content skills','Salary aligned'],gap:'Notice period needs confirmation'},
  {talentId:2,roleId:3,score:84,reasons:['Partnerships background','B2B growth experience','Negotiation skills'],gap:'Salary expectation may exceed this range'}
],activity:[]};
let employerRoleFilter=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3500)}
function navigate(v){if(state.mode==='employer'&&v==='talent')employerRoleFilter=null;state.view=v;render()}
function setMode(m){state.mode=m;state.view='overview';render()}
function filtered(){return talents.filter(t=>(!['saved','shortlist'].includes(state.view)||state.saved.has(t.id))&&(!employerRoleFilter||state.view!=='talent'||employerRole(employerRoleFilter).talentIds.includes(t.id))&&(state.category==='All functions'||t.category===state.category)&&(state.available==='Any availability'||t.availability===state.available)&&`${t.name} ${t.role} ${t.skills.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()))}
function render(){if(state.mode==='employer'){renderEmployer();return}const nav=[['overview','Overview','discover'],['profile','My Profile','profile'],['preferences','My Preferences','plan'],['opportunities','My Stars','saved'],['interest','Employer Interest','intro'],['privacy','Privacy','profile']];document.querySelector('#app').innerHTML=`<aside><div class="brand"><span class="star">✦</span><span>stars<br>collective<span style="color:#729059">.</span></span></div><div class="label">YOUR NEXT CHAPTER</div><nav>${nav.map(([v,l,i])=>`<button class="nav ${state.view===v?'active':''}" onclick="navigate('${v}')">${icon(i)}${l}</button>`).join('')}</nav><div class="aside-bottom"><div class="plan-note"><strong>Your talent profile</strong><p>Good work deserves to be discovered.</p><button class="text-btn" onclick="navigate('profile')">Manage my profile ↗</button></div><div class="company"><div class="avatar">SL</div><div><strong>${esc(state.profile.name)}</strong><small>Talent workspace</small></div></div></div></aside><main><header><span>Workspace <span style="margin:0 9px;color:#bac3ce">/</span> ${nav.find(x=>x[0]===state.view)?.[1]||'Overview'}</span><div class="switch" aria-label="Prototype perspective"><button onclick="setMode('employer')">Employer view</button><button class="selected" onclick="setMode('talent')">Talent view</button></div></header><div class="content">${body()}</div></main>`}
function body(){if(state.mode==='employer')return employerBody();if(['discover','saved'].includes(state.view)){let saved=state.view==='saved';return `<div class="heading"><div><div class="eyebrow">${saved?'YOUR TALENT COLLECTION':'PEOPLE, NOT JUST PROFILES'}</div><h1>${saved?'Keep great people close.':'Your next great hire starts here.'}</h1><p class="sub">${saved?'A thoughtful shortlist for your next opportunity.':'Discover professionals ready for their next chapter.'}</p></div><span class="badge">✦ Curated connections</span></div>${saved?'':`<section class="spotlight"><div><div class="eyebrow">THE COLLECTIVE EDIT / 01</div><h2>Small teams. Remarkable people.</h2><p>Meet professionals who bring initiative, versatility and hands-on experience to growing businesses.</p></div><button class="btn lime" onclick="showBrief()">Tailor my selection ↗</button></section>`}<div class="filters"><div class="search">${icon('discover')}<input aria-label="Search talent" placeholder="Search roles, skills or names" value="${esc(state.search)}" oninput="state.search=this.value;renderCards()"></div><select aria-label="Job function" onchange="state.category=this.value;renderCards()">${['All functions','Marketing','Business development','Sales','HR','Administration'].map(v=>`<option ${state.category===v?'selected':''}>${v}</option>`).join('')}</select><select aria-label="Availability" onchange="state.available=this.value;renderCards()">${['Any availability','Immediately','Within 1 month'].map(v=>`<option ${state.available===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="section-head"><h2>${saved?'Saved professionals':'Meet the collective'} <span id="resultCount"></span></h2><span>Singapore · Sample profiles</span></div><div class="grid" id="cards"></div><p class="footnote">Interactive prototype · Fictional people and companies · Changes reset when you refresh</p>`}
if(state.view==='intro')return heading('MEANINGFUL CONNECTIONS','Introductions','Every conversation starts with mutual interest.')+`<div class="callout">Try the full journey: request an introduction from a profile, then switch to Talent view to respond.</div>${state.requests.length?state.requests.map(r=>requestCard(r,false)).join(''):'<div class="panel empty"><h2>Your first conversation is ahead.</h2><p>Discover someone you would like to meet and send a thoughtful introduction.</p><button class="btn primary" style="margin-top:20px" onclick="navigate(\'discover\')">Discover talent</button></div>'}`;
if(state.view==='plan')return heading('A MEMBERSHIP THAT GROWS WITH YOU','Find your people. Build your team.','Explore subscription features. Pricing below is illustrative.')+`<div class="grid">${[['Free','S$0','Explore the collective',['Browse professional profiles','Save a personal shortlist','3 introductions per month']],['Collective','S$149','For teams hiring regularly',['Everything in Free','30 introductions per month','Tailored talent selections','Availability alerts']],['Team','S$299','Make hiring a shared effort',['Everything in Collective','100 introductions per month','Shared shortlists and team notes','Outreach and pipeline insights']]].map(([p,price,desc,features])=>`<section class="card plan ${p==='Collective'?'featured':''}"><span class="eyebrow">${p==='Collective'?'FOR GROWING TEAMS':p==='Team'?'HIRE TOGETHER':'START EXPLORING'}</span><h2>${p}</h2><div class="price">${price}<small> / month</small></div><p class="sub">${desc}</p><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="btn ${p==='Collective'?'primary':''}" onclick="selectPlan('${p}')">${state.plan===p?'Current demo plan':'Preview '+p}</button></section>`).join('')}</div><p class="footnote">Plan selection is a demo. No payment is collected. Premium features are illustrative.</p>`;
if(state.view==='profile')return profilePage();
return heading('YOUR NEXT CHAPTER','Good opportunities start with you.','Review the role, see the details and choose who you want to meet.')+`<div class="callout">Talent demo: you can review introductions sent to any sample professional.</div>${state.requests.length?state.requests.map(r=>requestCard(r,true)).join(''):`<div class="panel"><div class="eyebrow">A PROFILE THAT WORKS FOR YOU</div><h2>You’re ready to be discovered.</h2><p class="sub">No invitations yet. Switch to Employer view, open a talent profile and request an introduction to try the complete journey.</p><div class="actions"><button class="btn primary" onclick="setMode('employer')">Explore employer view</button><button class="btn" onclick="navigate('profile')">Edit my profile</button></div></div>`}`}
function employerAttention(){return employerDemo.attention.filter(item=>!item.done)}
function activeEmployerRoles(){return employerDemo.roles.filter(role=>role.status==='Active')}
function activeTopMatches(){return employerDemo.topMatches.filter(match=>employerRole(match.roleId).status==='Active')}
function employerRole(id){return employerDemo.roles.find(role=>role.id===id)}
function renderEmployer(){
 const nav=[['overview','Overview','overview'],['roles','Roles','roles'],['talent','Talent','discover'],['pipeline','Pipeline','pipeline'],['company','Company','company'],['team','Team','team'],['settings','Settings','settings']];
 const label=nav.find(([view])=>view===state.view)?.[1]||'Overview';
 const attention=employerAttention().length;
 document.querySelector('#app').innerHTML=`<div class="employer-shell"><aside class="employer-sidebar"><div class="brand"><span class="star">✦</span><span>stars<br>collective<span style="color:#729059">.</span></span></div><div class="label">HIRING WORKSPACE</div><nav aria-label="Employer navigation">${nav.map(([view,name,glyph])=>`<button class="nav ${state.view===view||(state.view==='shortlist'&&view==='talent')?'active':''}" onclick="navigate('${view}')">${icon(glyph)}<span>${name}</span>${view==='talent'&&state.saved.size?`<span class="count">${state.saved.size}</span>`:''}${view==='pipeline'&&attention?`<span class="count">${attention}</span>`:''}</button>`).join('')}</nav><div class="aside-bottom"><div class="employer-sidebar-note"><span class="eyebrow">YOUR WORKSPACE</span><strong>Make every next step count.</strong><p>Roles, relevant talent and conversations in one calm place.</p></div><div class="company"><div class="avatar">N</div><div><strong>Northstar Studio</strong><small>Employer workspace</small></div></div></div></aside><main class="employer-main"><header class="employer-header"><span>Workspace <span class="employer-breadcrumb">/</span> ${label}</span><div class="employer-header-actions"><span class="employer-company">Northstar Studio</span><button class="employer-bell" aria-label="Open hiring check-in, ${attention} items need attention" onclick="openCheckIn()">${icon('bell')}${attention?`<i>${attention}</i>`:''}</button><span class="employer-user" aria-label="Sarah Chen, Employer Admin">SC</span><div class="switch" aria-label="Prototype perspective"><button class="selected" onclick="setMode('employer')">Employer view</button><button onclick="setMode('talent')">Talent view</button></div></div></header><div class="content employer-content">${body()}</div></main></div>`;
 if(['talent','shortlist'].includes(state.view))renderCards();
}
function employerBody(){switch(state.view){
 case 'overview':return employerOverview();case 'roles':return employerRolesPage();case 'talent':case 'shortlist':return employerTalentPage();case 'pipeline':return employerPipelinePage();case 'company':return employerCompanyPage();case 'team':return employerTeamPage();case 'settings':return employerSettingsPage();default:return employerOverview();
}}
function employerTitle(kicker,title,copy,action=''){return `<div class="employer-page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`}
function employerOverview(){
 const metrics=[['Active Roles',activeEmployerRoles().length,'Roles are live and finding great talent.','roles'],['New Matches',employerDemo.newMatches,'Fresh talent matched to your roles.','talent'],['Need Attention',employerAttention().length,'Keep your pipeline moving forward.','checkin'],['Interviews This Week',employerDemo.interviewsThisWeek,'Candidates ready for the next step.','pipeline']];
 return `<div class="employer-dashboard">${employerTitle('HIRING COMMAND CENTRE','Good afternoon, Sarah 👋','Here’s where your hiring stands today.',`<button class="btn employer-primary" onclick="openCreateRole()">+ Create a New Role</button>`)}<div class="employer-metrics">${metrics.map(([label,count,detail,action])=>`<button class="employer-metric-card" onclick="${action==='checkin'?'openCheckIn()':`navigate('${action}')`}" aria-label="${count} ${label}. ${detail}"><span>${label}</span><strong>${count}</strong><small>${detail}</small><span class="employer-metric-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div class="employer-dashboard-grid"><section class="employer-surface employer-role-section"><div class="employer-section-heading"><div><h2>Your Active Roles</h2><p>Keep an eye on the searches moving now.</p></div><button class="employer-link" onclick="navigate('roles')">View all roles →</button></div>${employerRoleRows(activeEmployerRoles().slice(0,3))}</section><section class="employer-surface employer-attention-panel"><div class="employer-section-heading"><div><h2>Needs Your Attention</h2><p>${employerAttention().length} items to keep moving.</p></div><button class="employer-link" onclick="openCheckIn()">Hiring Check-in →</button></div>${employerAttention().slice(0,3).map(employerAttentionRow).join('')||'<p class="employer-empty-note">All caught up for now.</p>'}<button class="employer-link employer-view-all" onclick="openCheckIn()">View all items →</button></section></div><section class="employer-top-matches"><div class="employer-section-heading"><div><h2>Top Matches</h2><p>Promising people for your active roles. Scores are illustrative.</p></div><button class="employer-link" onclick="navigate('talent')">Explore talent →</button></div><div class="employer-match-grid">${activeTopMatches().map(employerMatchCard).join('')}</div></section><p class="employer-demo-footnote">Prototype data only · No live matching or employer notifications · Changes reset on refresh</p></div>`;
}
function employerRoleRows(roles,controls=false){return roles.length?`<div class="employer-role-list">${roles.map(role=>`<article class="employer-role-row"><div class="employer-role-name"><h3>${esc(role.title)}</h3><p>${esc(role.location)} · ${esc(role.salary)}</p></div><div class="employer-role-stats"><span><strong>${role.matches}</strong> Matches</span><span><strong>${role.shortlisted}</strong> Shortlisted</span><span><strong>${role.interviewing}</strong> Interviewing</span></div><span class="employer-status-pill ${role.status==='Active'?'is-active':''}">${role.status}</span><div class="employer-row-actions"><button class="employer-row-action" onclick="viewRoleMatches(${role.id})">View Matches →</button>${controls&&role.status==='Active'?`<button class="employer-row-action employer-close-role" onclick="openCloseRole(${role.id})">Close Role</button>`:''}</div></article>`).join('')}</div>`:'<p class="employer-empty-note">No active roles. Create one to start a demo search.</p>'}
function employerAttentionRow(item){return `<article class="employer-attention-item"><div class="employer-attention-avatar">${item.kind==='role'?'✦':item.name.split(' ').map(x=>x[0]).join('')}</div><div><strong>${esc(item.name)}</strong><p>${esc(item.detail)}</p></div><span class="employer-status-pill ${item.tone==='stale'?'is-stale':'is-attention'}">${esc(item.status)}</span><button class="employer-row-action" onclick="${item.kind==='role'?`openRoleStatus(${item.roleId})`:'openCheckIn()'}">${item.kind==='role'?'Confirm Role Status':item.stage==='Interview'?'Update Outcome':'Continue'} →</button></article>`}
function employerMatchCard(match){const t=talents.find(person=>person.id===match.talentId),role=employerRole(match.roleId);return `<article class="employer-match-card"><div class="employer-match-top"><div class="avatar" style="background:${t.color};color:${t.ink}">${t.initials}</div><div><h3>${t.name}</h3><p>${t.role}</p></div><span class="employer-match-score">${match.score}% <small>demo match</small></span></div><p class="employer-match-role">For ${esc(role.title)}</p><div class="employer-match-tags">${t.skills.map(skill=>`<span>${esc(skill)}</span>`).join('')}</div><div class="employer-match-meta"><span>${esc(t.availability)}</span><span>${esc(t.salary)} / month</span></div><div class="employer-match-reasons"><strong>Why Stars matched them</strong>${match.reasons.map(reason=>`<p><span>✓</span> ${esc(reason)}</p>`).join('')}<p class="employer-match-gap"><span>△</span> ${esc(match.gap)}</p></div><div class="employer-match-actions"><button class="btn ${state.saved.has(t.id)?'employer-shortlisted':''}" onclick="toggleSave(${t.id})">${state.saved.has(t.id)?'✓ Shortlisted':'+ Shortlist'}</button><button class="btn employer-primary" onclick="showProfile(${t.id})">View Profile</button></div></article>`}
function employerRolesPage(){return `<div class="employer-dashboard">${employerTitle('ROLE WORKSPACE','Your hiring roles','Start with a role, then review talent and move the right people forward.',`<button class="btn employer-primary" onclick="openCreateRole()">+ Create a New Role</button>`)}<section class="employer-surface employer-role-section"><div class="employer-section-heading"><div><h2>Active Roles</h2><p>${activeEmployerRoles().length} searches currently open.</p></div></div>${employerRoleRows(activeEmployerRoles(),true)}</section>${employerDemo.roles.filter(role=>role.status!=='Active').length?`<section class="employer-surface employer-closed-roles"><h2>Paused & closed</h2>${employerRoleRows(employerDemo.roles.filter(role=>role.status!=='Active'))}</section>`:''}<p class="employer-demo-footnote">Role activity and recommendations are illustrative. New roles stay in this session only.</p></div>`}
function employerTalentPage(){const saved=state.view==='shortlist',role=employerRoleFilter&&employerRole(employerRoleFilter);return `<div class="employer-dashboard">${employerTitle('TALENT WORKSPACE',saved?'Shortlisted Talent':'Talent discovery',saved?'People you have set aside for a closer look.':'Role recommendations come first. Search the sample collective when you want to explore manually.')}<div class="employer-tabs"><button class="${!saved?'active':''}" onclick="navigate('talent')">Discover Talent</button><button class="${saved?'active':''}" onclick="navigate('shortlist')">Shortlisted Talent <span>${state.saved.size}</span></button></div>${role?`<div class="employer-role-filter">Viewing sample talent for <strong>${esc(role.title)}</strong><button onclick="state.category='All functions';employerRoleFilter=null;render()">Clear role filter ×</button></div>`:''}<div class="filters"><div class="search">${icon('discover')}<input aria-label="Search talent" placeholder="Search roles, skills or names" value="${esc(state.search)}" oninput="state.search=this.value;renderCards()"></div><select aria-label="Job function" onchange="state.category=this.value;employerRoleFilter=null;renderCards()">${['All functions','Marketing','Business development','Sales','HR','Administration'].map(v=>`<option ${state.category===v?'selected':''}>${v}</option>`).join('')}</select><select aria-label="Availability" onchange="state.available=this.value;renderCards()">${['Any availability','Immediately','Within 1 month'].map(v=>`<option ${state.available===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="employer-section-heading"><div><h2>${saved?'Your shortlist':'Explore professionals'} <span id="resultCount"></span></h2><p>Singapore · Fictional sample profiles</p></div>${!saved?'<button class="employer-link" onclick="showBrief()">Tailor selection →</button>':''}</div><div class="grid" id="cards"></div><p class="employer-demo-footnote">Contact details remain private until a mutual introduction in this demo.</p></div>`}
function viewRoleMatches(id){employerRoleFilter=id;state.search='';state.available='Any availability';state.category='All functions';state.view='talent';render()}
function employerPipelinePage(){
 const stages=['Matched','Shortlisted','Introduction Sent','Talent Interested','Interview','Offer','Hired'];
 const counts=[activeTopMatches().length,state.saved.size,state.requests.filter(r=>r.status==='Awaiting response').length,state.requests.filter(r=>r.status==='Accepted').length,employerDemo.attention.filter(i=>i.stage==='Interview'&&!i.done).length,employerDemo.activity.filter(a=>a.stage==='Offer').length,employerDemo.roles.filter(r=>r.closure==='Hired Through Stars').length];
 return `<div class="employer-dashboard">${employerTitle('HIRING PIPELINE','Keep every conversation moving','A clear view from promising match to hiring outcome.',`<button class="btn employer-primary" onclick="openCheckIn()">Hiring Check-in ${employerAttention().length?`· ${employerAttention().length}`:''}</button>`)}<div class="employer-pipeline">${stages.map((stage,i)=>`<div class="employer-pipeline-stage"><span>${String(i+1).padStart(2,'0')}</span><strong>${stage}</strong><b>${counts[i]}</b></div>`).join('')}</div><div class="employer-dashboard-grid"><section class="employer-surface employer-attention-panel"><div class="employer-section-heading"><div><h2>Next actions</h2><p>Resolve or reconfirm each item.</p></div><button class="employer-link" onclick="openCheckIn()">Open check-in →</button></div>${employerAttention().map(employerAttentionRow).join('')||'<p class="employer-empty-note">No pending actions.</p>'}</section><section class="employer-surface"><div class="employer-section-heading"><div><h2>Recent activity</h2><p>Demo updates in this session.</p></div></div>${employerDemo.activity.length?employerDemo.activity.slice().reverse().map(a=>`<p class="employer-activity"><strong>${esc(a.name)}</strong><span>${esc(a.label)}</span></p>`).join(''):'<p class="employer-empty-note">Updates from Hiring Check-in will appear here.</p>'}</section></div><section class="employer-surface employer-introductions"><div class="employer-section-heading"><div><h2>Introductions</h2><p>Mutual interest still starts the conversation.</p></div><button class="employer-link" onclick="navigate('talent')">Discover talent →</button></div>${state.requests.length?state.requests.map(r=>requestCard(r,false)).join(''):'<div class="employer-empty-note">No introductions yet. Open a talent profile to request one.</div>'}</section><p class="employer-demo-footnote">Pipeline stages are a frontend preview. Only demo introductions and session actions update here.</p></div>`
}
function employerCompanyPage(){return `<div class="employer-dashboard">${employerTitle('COMPANY WORKSPACE','Northstar Studio','A concise hiring identity for this demo workspace.')}<section class="employer-surface employer-company-page"><div class="employer-company-mark">N</div><div><h2>Northstar Studio</h2><p>Singapore · Creative services · 11–50 people</p><p>We build practical brand and digital experiences for growing teams. This is illustrative company information for the prototype.</p><div class="employer-company-facts"><div><span>Industry</span><strong>Creative services</strong></div><div><span>Work arrangement</span><strong>Hybrid</strong></div><div><span>Benefits</span><strong>Flexible work · Learning budget</strong></div><div><span>Website</span><strong>Not connected in demo</strong></div></div></div></section></div>`}
function employerTeamPage(){return `<div class="employer-dashboard">${employerTitle('YOUR PEOPLE','Hiring Team','The people shaping each hiring decision.')}<section class="employer-surface employer-team-page"><div class="avatar">SC</div><div><h2>Sarah Chen</h2><p>Employer Admin · Northstar Studio</p><small>Team invitations and permissions are not connected in this prototype.</small></div></section></div>`}
function employerSettingsPage(){const plans=[['Free','S$0','Explore the collective',['Browse professional profiles','Save a personal shortlist','3 introductions per month']],['Collective','S$149','For teams hiring regularly',['Everything in Free','30 introductions per month','Tailored talent selections','Availability alerts']],['Team','S$299','Make hiring a shared effort',['Everything in Collective','100 introductions per month','Shared shortlists and team notes','Outreach and pipeline insights']]];return `<div class="employer-dashboard">${employerTitle('WORKSPACE CONTROLS','Settings','Review your workspace and illustrative membership options.')}<div class="employer-settings-summary"><section class="employer-surface"><h2>Workspace</h2><p>Northstar Studio · Singapore</p><small>Company and team details are sample information.</small></section><section class="employer-surface"><h2>Notifications</h2><p>Hiring Check-in is available from the dashboard and Pipeline.</p><small>No emails or browser notifications are sent.</small></section></div><div class="employer-section-heading"><div><h2>Membership</h2><p>Current demo plan: ${esc(state.plan)}. No payment is collected.</p></div></div><div class="employer-plan-grid">${plans.map(([name,price,description,features])=>`<section class="employer-surface employer-plan ${name===state.plan?'current':''}"><span class="eyebrow">${name==='Free'?'GET STARTED':name==='Collective'?'GROWING TEAMS':'HIRE TOGETHER'}</span><h3>${name}</h3><div class="employer-plan-price">${price}<small> / month</small></div><p>${description}</p><ul>${features.map(feature=>`<li>${feature}</li>`).join('')}</ul><button class="btn ${name===state.plan?'':'employer-primary'}" onclick="selectPlan('${name}')">${state.plan===name?'Current demo plan':'Preview '+name}</button></section>`).join('')}</div><p class="employer-demo-footnote">Billing and membership access are illustrative. There is no payment flow.</p></div>`}
function openCreateRole(){modal(`<div class="employer-modal"><span class="eyebrow">ROLE BRIEF · DEMO</span><h2>Create a New Role</h2><p class="sub">Describe the work. Stars will show a session-only role preview.</p><form onsubmit="createEmployerRole(event)"><div class="form-grid"><label>Role Title<input name="title" required maxlength="100" placeholder="e.g. Sales Executive"></label><label>Location<input name="location" required maxlength="100" placeholder="e.g. Singapore"></label><label>Salary Minimum (SGD)<input name="min" type="number" min="0" required placeholder="3500"></label><label>Salary Maximum (SGD)<input name="max" type="number" min="0" required placeholder="5000"></label><label>Employment Type<select name="type"><option>Full-time</option><option>Part-time</option><option>Contract</option><option>Internship</option></select></label><label>Work Arrangement<select name="arrangement"><option>Hybrid</option><option>On-site</option><option>Remote</option></select></label><label class="full">Availability Requirement<select name="availability"><option>Flexible</option><option>Immediately</option><option>Within 1 month</option><option>Within 2 months</option></select></label><label class="full">Job Description / Hiring Brief<textarea name="brief" required maxlength="2000" placeholder="What will this person own and deliver?"></textarea></label><label class="full">Must Have Skills<input name="mustHave" maxlength="250" placeholder="Separate skills with commas"></label><label class="full">Preferred Skills<input name="preferred" maxlength="250" placeholder="Optional"></label></div><p class="employer-form-error" id="role-error" role="alert"></p><div class="actions"><button type="button" class="btn" onclick="document.querySelector('#modal').close()">Cancel</button><button type="submit" class="btn employer-primary">Find Stars</button></div></form></div>`)}
function createEmployerRole(e){e.preventDefault();const f=new FormData(e.target),min=Number(f.get('min')),max=Number(f.get('max'));if(max<min){document.querySelector('#role-error').textContent='Salary maximum must be at least the minimum.';return}const role={id:Math.max(...employerDemo.roles.map(r=>r.id))+1,title:String(f.get('title')).trim(),location:String(f.get('location')).trim(),salary:`SGD ${min.toLocaleString()} – ${max.toLocaleString()}`,matches:0,shortlisted:0,interviewing:0,category:'All functions',talentIds:[],status:'Active',brief:String(f.get('brief')).trim(),mustHave:String(f.get('mustHave')).trim(),preferred:String(f.get('preferred')).trim(),type:String(f.get('type')),arrangement:String(f.get('arrangement')),availability:String(f.get('availability'))};employerDemo.roles.unshift(role);document.querySelector('#modal').close();navigate('roles');toast('Demo role created. Live matching is not connected.')}
function openRoleStatus(id){const role=employerRole(id);modal(`<div class="employer-modal"><span class="eyebrow">ROLE CHECK-IN</span><h2>${esc(role.title)}</h2><p class="sub">Is this search still active? Confirm the status or close the role for this demo session.</p><div class="actions"><button class="btn employer-primary" onclick="confirmRoleActive(${id})">Still Active · No Change</button><button class="btn" onclick="openCloseRole(${id})">Close Role</button></div></div>`)}
function confirmRoleActive(id){const item=employerDemo.attention.find(a=>a.kind==='role'&&a.roleId===id&&!a.done);if(item)item.done=true;employerDemo.activity.push({name:employerRole(id).title,label:'Role status reconfirmed · No Change',stage:'Active'});document.querySelector('#modal').close();render();toast('Role status reconfirmed in this demo session.')}
function openCloseRole(id){const role=employerRole(id),candidates=(role.talentIds.length?role.talentIds:talents.map(t=>t.id)).map(tid=>talents.find(t=>t.id===tid));modal(`<div class="employer-modal"><span class="eyebrow">ROLE OUTCOME · DEMO</span><h2>Close ${esc(role.title)}</h2><p class="sub">What happened with this hiring need?</p><form onsubmit="confirmRoleClose(event,${id})"><label>Outcome<select name="outcome" required onchange="document.querySelector('#hired-choice').hidden=this.value!=='Hired Through Stars';document.querySelector('#hired-choice select').required=this.value==='Hired Through Stars'"><option value="">Select an outcome</option>${['Hired Through Stars','Hired Outside Stars','Filled Internally','Hiring Paused','Role Cancelled','No Suitable Candidate'].map(v=>`<option>${v}</option>`).join('')}</select></label><label id="hired-choice" hidden>Who was hired?<select name="candidate"><option value="">Select a sample candidate</option>${candidates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><div class="actions"><button type="button" class="btn" onclick="document.querySelector('#modal').close()">Cancel</button><button type="submit" class="btn employer-primary">Confirm Hire / Outcome</button></div></form><p class="employer-demo-footnote">No placement record is created.</p></div>`)}
function confirmRoleClose(e,id){e.preventDefault();const f=new FormData(e.target),role=employerRole(id),outcome=String(f.get('outcome'));role.status=outcome==='Hiring Paused'?'Paused':'Closed';role.closure=outcome;role.hiredTalentId=outcome==='Hired Through Stars'?Number(f.get('candidate')):null;employerDemo.attention.filter(a=>a.roleId===id).forEach(a=>a.done=true);employerDemo.activity.push({name:role.title,label:outcome+(role.hiredTalentId?' · '+talents.find(t=>t.id===role.hiredTalentId).name:''),stage:outcome==='Hired Through Stars'?'Hired':role.status});document.querySelector('#modal').close();navigate('roles');toast('Role outcome saved in this demo session only.')}
function openCheckIn(){const items=employerAttention();modal(`<div class="employer-checkin"><div class="eyebrow">A MOMENT TO MOVE THINGS FORWARD</div><h2>Hiring Check-in</h2><p class="sub">${items.length} item${items.length===1?'':'s'} need your attention.<br>Keep your pipeline moving forward.</p>${items.length?items.map(item=>`<article class="employer-checkin-item"><div class="employer-checkin-heading"><div class="employer-attention-avatar">${item.kind==='role'?'✦':item.name.split(' ').map(x=>x[0]).join('')}</div><div><h3>${esc(item.name)}</h3><p>${esc(item.role)}</p></div><span class="employer-status-pill ${item.tone==='stale'?'is-stale':'is-attention'}">${esc(item.status)}</span></div><p class="employer-checkin-detail">${esc(item.detail)}</p>${item.kind==='role'?`<div class="employer-checkin-actions"><button onclick="confirmRoleActive(${item.roleId})">Still Active · No Change</button><button onclick="openCloseRole(${item.roleId})">Close Role</button></div>`:`<div class="employer-checkin-actions"><button onclick="setCheckInOutcome(${item.id},'Progressed')">Progressed</button><button onclick="setCheckInOutcome(${item.id},'Another Interview')">Another Interview</button><button onclick="openRejectionFeedback(${item.id})">Rejected</button><button onclick="setCheckInOutcome(${item.id},'No Change')">No Change</button></div>`}</article>`).join(''):'<div class="employer-empty-note">All caught up. Thanks for keeping your hiring current.</div>'}<div class="employer-checkin-footer"><button class="btn" onclick="document.querySelector('#modal').close()">Done</button><button class="employer-link" onclick="document.querySelector('#modal').close();navigate('pipeline')">View all items →</button></div><p class="employer-demo-footnote">Session-only updates. No reminders or messages are sent.</p></div>`)}
function setCheckInOutcome(id,outcome,reason=''){const item=employerDemo.attention.find(a=>a.id===id);if(!item||item.done)return;item.done=true;item.outcome=outcome;item.reason=reason;item.checkedAt=new Date().toISOString();item.stage=outcome==='Progressed'?'Offer':outcome==='Another Interview'?'Interview':outcome==='Rejected'?'Rejected':item.stage;employerDemo.activity.push({name:item.name,label:outcome+(reason?' · '+reason:''),stage:item.stage});render();openCheckIn();toast(outcome==='No Change'?'Status reconfirmed in this demo session.':'Hiring outcome updated in this demo session.')}
function openRejectionFeedback(id){const item=employerDemo.attention.find(a=>a.id===id);modal(`<div class="employer-modal"><span class="eyebrow">OPTIONAL MATCHING FEEDBACK</span><h2>What is the main reason?</h2><p class="sub">${esc(item.name)} · ${esc(item.role)}</p><form onsubmit="submitRejectionFeedback(event,${id})"><label>Reason (optional)<select name="reason" onchange="const other=document.querySelector('#rejection-other');other.hidden=this.value!=='Other';other.querySelector('input').required=this.value==='Other'"><option value="">Skip feedback</option>${['Experience','Skills','Salary','Availability','Location','Industry','Candidate Withdrew','Role Changed','Other'].map(v=>`<option>${v}</option>`).join('')}</select></label><label id="rejection-other" hidden>Other reason<input name="other" maxlength="180" placeholder="Briefly describe the reason"></label><div class="actions"><button type="button" class="btn" onclick="openCheckIn()">Back</button><button type="submit" class="btn employer-primary">Save outcome</button></div></form></div>`)}
function submitRejectionFeedback(e,id){e.preventDefault();const f=new FormData(e.target),reason=String(f.get('reason')||''),detail=reason==='Other'?String(f.get('other')||'').trim():reason;setCheckInOutcome(id,'Rejected',detail)}
function heading(e,h,s){return `<div class="heading"><div><div class="eyebrow">${e}</div><h1>${h}</h1><p class="sub">${s}</p></div></div>`}
function renderCards(){const list=filtered(),saved=['saved','shortlist'].includes(state.view);document.querySelector('#resultCount').textContent=`(${list.length})`;document.querySelector('#cards').innerHTML=list.length?list.map(t=>`<article class="card"><div class="card-top"><div class="avatar" style="background:${t.color};color:${t.ink}">${t.initials}</div><div><h3>${t.name}</h3><p class="role">${t.role}</p></div><button class="save ${state.saved.has(t.id)?'saved':''}" aria-label="${state.saved.has(t.id)?'Unsave':'Save'} ${t.name}" aria-pressed="${state.saved.has(t.id)}" onclick="toggleSave(${t.id})">${icon('saved')}</button></div><p class="meta">Singapore <span style="margin:0 6px">·</span> ${t.years} years of experience</p><div class="tags">${t.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="fit"><strong>WHAT THEY BRING</strong>${t.note}</div><div class="card-bottom"><span class="available">${t.availability==='Immediately'?'Available now':'Open to opportunities'}</span><button class="btn" onclick="showProfile(${t.id})">Meet ${t.name.split(' ')[0]} ↗</button></div></article>`).join(''):`<div class="panel empty"><h2>${saved?'No shortlisted talent yet.':'No matching professionals.'}</h2><p>${saved?'Save someone from Talent discovery to build your shortlist.':'Try another role, skill or availability.'}</p><button class="btn" style="margin-top:20px" onclick="state.search='';state.category='All functions';state.available='Any availability';navigate('talent')">Explore all talent</button></div>`}
function toggleSave(id){state.saved.has(id)?state.saved.delete(id):state.saved.add(id);render()}
function modal(html){const d=document.querySelector('#modal');d.innerHTML=`<button class="close" aria-label="Close dialog" onclick="document.querySelector('#modal').close()">×</button>${html}`;if(!d.open)d.showModal()}
function showProfile(id){const t=talents.find(t=>t.id===id);modal(`<div class="eyebrow">MEET THE COLLECTIVE</div><h2>${t.name}</h2><p class="sub">${t.role} · Singapore · ${t.years} years’ experience</p><div class="tags">${t.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="fit"><strong>PROFESSIONAL SNAPSHOT</strong>${t.note}</div><h3 style="font-size:16px">A contribution worth knowing</h3><p class="sub">${t.achievement}</p><p style="font-size:12px;color:#7e8b9b">Sample achievement · Self-reported</p><div class="callout">${t.salary} / month<br>Available: ${t.availability}<br>Interested in: Full-time · Hybrid or on-site</div><p class="sub">Contact details are shared only after a mutual introduction.</p><button class="btn primary" onclick="introForm(${id})">Request an introduction</button>`)}
function introForm(id){if(state.requests.some(r=>r.talentId===id)){toast('You already have an introduction with this professional.');return}modal(`<h2>Make the first move.</h2><p class="sub">Introduce your opportunity to ${talents.find(t=>t.id===id).name}. Give them the details they need to decide.</p><form onsubmit="sendIntro(event,${id})"><div class="form-grid"><label class="full">Role title<input name="role" placeholder="e.g. Marketing Executive" required maxlength="100"></label><label class="full">Monthly salary range<input name="salary" placeholder="e.g. S$4,000–5,000" required maxlength="100"></label><label class="full">Why would you like to meet?<textarea name="message" required maxlength="1000" placeholder="Share a little about the role and why their experience caught your eye."></textarea></label></div><div class="actions"><button class="btn primary" type="submit">Send demo introduction</button></div><p class="sub" style="font-size:12px">Simulation only. No message is sent to a real person.</p></form>`)}
function sendIntro(e,id){e.preventDefault();const f=new FormData(e.target);state.requests.push({id:Date.now(),talentId:id,role:f.get('role').trim(),salary:f.get('salary').trim(),message:f.get('message').trim(),status:'Awaiting response'});document.querySelector('#modal').close();navigate('pipeline');toast('Introduction created. Switch to Talent view to respond.')}
function requestCard(r,talent){let t=talents.find(t=>t.id===r.talentId);return `<article class="request"><div class="section-head" style="margin:0 0 12px"><h3>${esc(r.role)}</h3><span class="status">${r.status}</span></div><p><strong>${talent?'Northstar Studio → '+t.name:t.name+' · '+t.role}</strong></p><p>${esc(r.salary)} / month · Singapore</p><p style="margin-top:12px">${esc(r.message)}</p>${talent&&r.status==='Awaiting response'?`<div class="actions"><button class="btn primary" onclick="respond(${r.id},'Accepted')">Accept introduction</button><button class="btn" onclick="respond(${r.id},'Declined')">Decline</button></div>`:''}${r.status==='Accepted'?'<div class="callout">You’re connected. In the full platform, both parties can now exchange contact details and arrange a conversation.</div>':''}</article>`}
function respond(id,status){state.requests.find(r=>r.id===id).status=status;render();toast(status==='Accepted'?'Introduction accepted. Your employer view is updated.':'Introduction declined. Your employer view is updated.')}
function saveProfile(e){e.preventDefault();state.profile=Object.fromEntries(new FormData(e.target));render();toast('Profile saved for this demo session.')}
function selectPlan(p){state.plan=p;render();toast(p+' selected for the demo. No payment collected.')}
function showBrief(){modal(`<h2>Who would you like to meet?</h2><p class="sub">Tailor this sample selection to your next hiring need.</p><form onsubmit="applyBrief(event)"><div class="form-grid"><label class="full">Job function<select name="category">${['Marketing','Business development','Sales','HR','Administration'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="full">When should they be available?<select name="available"><option>Any availability</option><option>Immediately</option><option>Within 1 month</option></select></label></div><div class="actions"><button type="submit" class="btn primary">Show my selection</button></div></form>`)}
function applyBrief(e){e.preventDefault();let f=new FormData(e.target);state.category=f.get('category');state.available=f.get('available');state.search='';employerRoleFilter=null;document.querySelector('#modal').close();navigate('talent')}
if(location.hash==='#profile'){state.mode='talent';state.view='profile';}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_talent',description:'Filter the sample talent discovery view by professional function.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['All functions','Marketing','Business development','Sales','HR','Administration']}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['All functions','Marketing','Business development','Sales','HR','Administration'].includes(input.category))throw new Error('Unknown job function');state.category=input.category;state.search='';state.available='Any availability';state.mode='employer';navigate('talent');return {count:filtered().length,category:state.category}}})).catch(()=>{})}catch{}}
